implementations.
func walkTree(t *treeNode) (int, error) {
switch val := t.val.(type) {
case nil:
return 0, errors.New("invalid expression")
case number:
// we know that t.val is of type number, so return the
// int value
return int(val), nil
case operator:
// we know that t.val is of type operator, so
// find the values of the left and right children,
then
// call the process() method on operator to return the
// result of processing their values.
left, err := walkTree(t.lchild)
if err != nil {
return 0, err
}
right, err := walkTree(t.rchild)
if err != nil {
return 0, err
}
return val.process(left, right), nil
default:
// if a new treeVal type is defined, but walkTree
wasn't updated
// to process it, this detects it
return 0, errors.New("unknown node type")
}
}
